const topics = [
  { id: 'cmmc-01', title: 'CMMC readiness is a board-level operating issue', sourceUrl: 'https://www.govconic.com/cmmc-readiness-board-level-operating-issue' },
  { id: 'cmmc-02', title: 'The quiet CMMC gap is often in evidence handling', sourceUrl: 'https://www.govconic.com/quiet-cmmc-gap-evidence-handling' },
  { id: 'cmmc-03', title: 'Why CMMC scoping assumptions drift over time', sourceUrl: 'https://www.govconic.com/why-cmmc-scoping-assumptions-drift' },
  { id: 'cmmc-04', title: 'The overlooked CMMC control that creates audit friction', sourceUrl: 'https://www.govconic.com/overlooked-cmmc-control-audit-friction' }
];
const usedIds = Array.isArray(staticData.usedIds) ? staticData.usedIds : [];
let available = topics.filter((topic) => !usedIds.includes(topic.id));
if (available.length === 0) {
  staticData.usedIds = [];
  available = topics;
}
const topic = available[0];
const nextUsedIds = Array.from(new Set([...(usedIds || []), topic.id]));
staticData.usedIds = nextUsedIds;
return [{ json: { topicId: topic.id, topicTitle: topic.title, topicSourceUrl: topic.sourceUrl } }];

